<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useAuthStore } from '@/stores/auth'
import { ApiError } from '@/services/api'
import { listInstances, listUsers, transferOwner } from '@/services/resources'
import { resetAfterOwnerTransferConflict } from '@/services/ownerTransferState'
import type { Instance, User } from '@/types/api'
import PageState from '@/components/PageState.vue'; import StatusBadge from '@/components/StatusBadge.vue'; import ModalDialog from '@/components/ModalDialog.vue'
const auth=useAuthStore(), instances=ref<Instance[]>([]),users=ref<User[]>([]),loading=ref(true),error=ref(''),notice=ref(''),selected=ref<Instance|null>(null),saving=ref(false),formError=ref(''),form=ref({to_user_id:'',reason:''})
const userMap=computed(()=>Object.fromEntries(users.value.map(u=>[u.id,u])))
const candidates=computed(()=>users.value.filter(u=>u.status==='active'&&u.team_id===selected.value?.team_id&&['team_admin','staff'].includes(u.role)))
function owner(id:string|null){if(!id)return '未分配';return userMap.value[id]?.display_name||(id===auth.user?.id?auth.user.display_name:'受限用户')}
async function load(){loading.value=true;error.value='';try{instances.value=await listInstances();users.value=auth.isAdmin?await listUsers():auth.user?[auth.user]:[]}catch(e){error.value=e instanceof ApiError?e.message:'实例载入失败。'}finally{loading.value=false}}
function openTransfer(item:Instance){selected.value=item;form.value={to_user_id:item.current_owner_user_id||'',reason:''};formError.value='';notice.value=''}
async function submit(){if(!selected.value)return;saving.value=true;formError.value='';const attemptedId=selected.value.id;try{await transferOwner(attemptedId,{to_user_id:form.value.to_user_id,expected_instance_version:selected.value.version,reason:form.value.reason});selected.value=null;await load()}catch(e){if(e instanceof ApiError&&e.status===409){await load();if(error.value){selected.value=null;notice.value='实例已发生版本冲突且最新数据刷新失败，请先重新加载列表。'}else{const state=resetAfterOwnerTransferConflict(instances.value,attemptedId);selected.value=state.selected;notice.value=state.message}}else formError.value=e instanceof ApiError?e.message:'转交失败。'}finally{saving.value=false}}
onMounted(load)
</script>
<template><section><header class="page-header"><div><span class="eyebrow">Sites</span><h1>网站实例</h1><p>{{ auth.user?.role==='staff'?'仅显示由你负责的实例。':'显示当前权限范围内的实例，可按授权转交负责人。' }}</p></div><span class="date-chip">{{ instances.length }} 个可见实例</span></header>
<div v-if="notice" class="alert alert-neutral page-alert">{{ notice }}</div><PageState :loading="loading" :error="error" :empty="!instances.length" empty-title="暂无网站实例" empty-text="本阶段没有实例创建接口；实例出现后会自动显示在这里。" @retry="load"><div class="content-card"><div class="table-wrap"><table><thead><tr><th>域名</th><th>状态</th><th>负责人</th><th>创建时间</th><th>版本</th><th v-if="auth.capabilities.transfer_owner" class="align-right">操作</th></tr></thead><tbody><tr v-for="item in instances" :key="item.id"><td><div><b>{{ item.fqdn }}</b><small class="mono-id">{{ item.id }}</small></div></td><td><StatusBadge :value="item.status"/></td><td>{{ owner(item.current_owner_user_id) }}</td><td>{{ new Date(item.created_at).toLocaleString('zh-CN') }}</td><td>v{{ item.version }}</td><td v-if="auth.capabilities.transfer_owner" class="align-right"><button class="btn-link" @click="openTransfer(item)">转交负责人</button></td></tr></tbody></table></div></div></PageState>
<ModalDialog :open="!!selected" title="转交实例负责人" :description="selected?.fqdn" @close="selected=null"><form class="modal-form" @submit.prevent="submit"><div v-if="formError" class="alert">{{ formError }}</div><label>新负责人<select v-model="form.to_user_id" required><option value="" disabled>选择同团队有效用户</option><option v-for="user in candidates" :key="user.id" :value="user.id">{{ user.display_name }} · {{ user.email }}</option></select></label><label>转交原因<textarea v-model.trim="form.reason" required maxlength="500" rows="4" placeholder="记录此次转交的业务原因"/></label><p class="form-hint">将使用实例版本 v{{ selected?.version }} 执行乐观锁检查。</p><footer><button type="button" class="btn btn-secondary" @click="selected=null">取消</button><button class="btn btn-primary" :disabled="saving">{{ saving?'转交中…':'确认转交' }}</button></footer></form></ModalDialog></section></template>
